<script>
import Group from '@/domain/group'
import GcepQuickGuideLink from '../links/GcepQuickGuideLink.vue';
import VcepProtocolLink from '../links/VcepProtocolLink.vue';
import ScvcepProtocolLink from '../links/ScvcepProtocolLink.vue';
import EditIconButton from '@/components/buttons/EditIconButton.vue'
import RichTextEditor from '@/components/prosekit/RichTextEditor.vue'
import InlineTextDiff from '@/components/groups/InlineTextDiff.vue'
import { htmlFromMarkdown } from '@/markdown-utils';

export default {
    name: "ScopeDescriptionForm",
    components: {
        GcepQuickGuideLink,
        VcepProtocolLink,
        ScvcepProtocolLink,
        EditIconButton,
        RichTextEditor,
        InlineTextDiff,
    },
    inject: {
        scopeOfWorkComparisonState: { default: null },
    },
    props: {
        editing: {
          type: Boolean,
          required: false,
          default: true
        },
        errors: {
          type: Object,
          required: false,
          default: () => ({}),
        },
        readonly: {
          type: Boolean,
          default: false
        }
    },
    emits: [
        "update:editing",
        "update:group",
        "update"
    ],
    computed: {
        submittedComparison() {
            const comparison = this.scopeOfWorkComparisonState?.comparison;
            return comparison?.value ?? comparison ?? null;
        },
        scopeDescriptionChange() {
            const comparison = this.submittedComparison;
            if (comparison?.unavailable_sections?.includes('scope_description')) {
                return null;
            }
            return comparison?.changes?.find(change =>
                change.section === 'scope_description' && change.before !== change.after
            ) ?? null;
        },
        comparisonHeading() {
            return this.submittedComparison?.mode === 'approved_baseline'
                ? 'Changes since approved baseline'
                : this.submittedComparison?.source === 'live'
                    ? 'Changes since last submission'
                    : 'Changes since previous review round';
        },
        group: {
            get() {
                return this.$store.getters["groups/currentItem"] || new Group();
            },
            set(value) {
                this.$store.commit("groups/addItem", value);
            }
        },
        htmlScopeDescription() {
            return htmlFromMarkdown(this.group.expert_panel.scope_description);
        },
        expertPanel() {
          return this.group?.expert_panel || {};
        },
        genes() {
          const g = this.expertPanel?.genes;
          return Array.isArray(g) ? g : [];
        },
    }
}
</script>
<template>
  <div>
    <header class="flex justify-between items-center">
      <h4>Description of Scope</h4>
      <EditIconButton
        v-if="hasAnyPermission(['groups-manage', ['application-edit', group]]) && !editing && !readonly"
        @click="$emit('update:editing', true)"
      />
    </header>
    <div class="mt-2 text-sm">
      <p v-if="group.is_vcep">
        Describe the scope of work of the Expert Panel including the disease area(s), genes being addressed, and any specific rationale for choosing the condition(s). See the
        <VcepProtocolLink /> for more information.
      </p>
      <p v-if="group.is_scvcep">
        Describe the scope of work of the Expert Panel including the disease area(s), genes being addressed, and any specific rationale for choosing the condition(s). See the
        <ScvcepProtocolLink /> for more information.
      </p>
      <div v-if="group.is_gcep">
        Describe the scope of work of the expert panel including the following:
      
        <ul class="list-disc list-inside mt-2">
          <li>Describe the disease area of focus</li>
          <li>Indicate why curation efforts would benefit this disease area</li>
          <li>Indicate how the gene list will be prioritized</li>
          <li>Describe plans to collaborate with other GCEPs on any genes on your gene list that overlap in scope</li>
          <li>See the <GcepQuickGuideLink /> for more information</li>
        </ul>
      </div>

      <transition name="fade" mode="out-in">
        <div v-if="editing" class="mt-2">
          <RichTextEditor
            v-model="group.expert_panel.scope_description"
            @update:model-value="$emit('update')"
          />
        </div>
        <div v-else-if="!scopeDescriptionChange" class="border-2 mt-8 p-2">
          <div v-if="group.expert_panel.scope_description" v-html="htmlScopeDescription" />
          <p v-else class="well cursor-pointer" @click="showForm">
            A description of scope has not yet been provided.
          </p>
        </div>
      </transition>
      <section
        v-if="scopeDescriptionChange"
        class="mt-3 rounded border bg-white p-3 text-sm"
        :aria-label="comparisonHeading"
      >
        <h5 class="font-semibold">{{ comparisonHeading }}</h5>
        <p class="mb-2 text-xs text-gray-600">
          {{ submittedComparison?.source === 'live'
            ? 'Current saved draft changes; unsaved edits are not included.'
            : 'Submitted changes only; unsubmitted edits are not included.' }}
          Added words are highlighted; removed words are struck through.
        </p>
        <InlineTextDiff
          :before="scopeDescriptionChange.before ?? ''"
          :after="scopeDescriptionChange.after ?? ''"
        />
      </section>
    </div>
  </div>
</template>
